def r = ctx.resourceSpans[0];
def s = r.scopeSpans[0].spans[0];
def attrs = new HashMap();
if (r.resource != null && r.resource.attributes != null) {
  for (def a : r.resource.attributes) {
    for (def entry : a.value.entrySet()) { attrs[a.key] = entry.getValue(); }
  }
}
if (s.attributes != null) {
  for (def a : s.attributes) {
    for (def entry : a.value.entrySet()) { attrs[a.key] = entry.getValue(); }
  }
}
long start = Long.parseLong(s.startTimeUnixNano.toString());
long end = s.endTimeUnixNano != null ? Long.parseLong(s.endTimeUnixNano.toString()) : start;
ctx['@timestamp'] = Instant.ofEpochMilli(start / 1000000).toString();
def span = new HashMap();
span.trace_id = s.traceId;
span.span_id = s.spanId;
span.parent_span_id = s.parentSpanId;
span.name = s.name;
span.kind = s.kind;
span.duration_ms = Math.max(0.0, (end - start) / 1000000.0);
span.service_name = attrs['service.name'];
span.asset = attrs['alertflex.asset.name'];
span.project_id = attrs['alertflex.project.id'];
span.source = attrs['service.name'] == 'altprobe' ? 'internal' : 'gateway-native';
span.http_method = attrs.containsKey('http.request.method') ? attrs['http.request.method'] : attrs['http.method'];
span.http_url = attrs.containsKey('url.full') ? attrs['url.full'] : (attrs.containsKey('http.url') ? attrs['http.url'] : (attrs.containsKey('http.target') ? attrs['http.target'] : attrs['url.path']));
span.agent_key = attrs['alertflex.agent.key'];
span.status = s.status != null && s.status.code != null ? s.status.code.toString() : '0';
def code = attrs.containsKey('http.response.status_code') ? attrs['http.response.status_code'] : attrs['http.status_code'];
if (code != null) { span.http_status = Integer.parseInt(code.toString()); }
span.error = span.status == '2' || (span.http_status != null && span.http_status >= 500);
ctx.span = span;
